solution_code:
interface Sortable {
    int[] sort(int[] arr);
}

class BubbleSorter implements Sortable {
    public int[] sort(int[] arr) {
        int[] result = arr.clone();
        for (int i = 0; i < result.length; i++) {
            for (int j = 0; j < result.length - i - 1; j++) {
                if (result[j] > result[j + 1]) {
                    int temp = result[j];
                    result[j] = result[j + 1];
                    result[j + 1] = temp;
                }
            }
        }
        return result;
    }
}

