import java.util.*;

public class StudentManager {
    private Map<String, int[]> students = new HashMap<>();

    public void addStudent(String name, int[] scores) {
        students.put(name, scores);
    }

    public double getAverage(String name) {
        if (!students.containsKey(name)) return -1;
        int[] scores = students.get(name);
        double sum = 0;
        for (int s : scores) sum += s;
        return sum / scores.length;
    }

    public String getTopStudent() {
        String top = null;
        double maxAvg = -1;
        for (String name : students.keySet()) {
            double avg = getAverage(name);
            if (avg > maxAvg) { maxAvg = avg; top = name; }
        }
        return top;
    }
}
